const THEME_KEY = "datanile_theme";

export const THEME_PALETTE = {
  "--nile-deep": [
    "oklch(0.32 0.07 235)",
    "oklch(0.28 0.08 260)",
    "oklch(0.35 0.08 155)",
    "oklch(0.30 0.09 20)",
    "oklch(0.25 0.05 280)",
  ],
  "--terracotta": [
    "oklch(0.58 0.12 45)",
    "oklch(0.62 0.14 30)",
    "oklch(0.55 0.13 60)",
    "oklch(0.50 0.15 15)",
    "oklch(0.60 0.10 80)",
  ],
  "--reed": [
    "oklch(0.55 0.10 150)",
    "oklch(0.58 0.12 140)",
    "oklch(0.50 0.09 170)",
    "oklch(0.62 0.11 130)",
    "oklch(0.48 0.08 180)",
  ],
  "--gold": [
    "oklch(0.76 0.12 75)",
    "oklch(0.80 0.14 70)",
    "oklch(0.72 0.13 85)",
    "oklch(0.78 0.11 60)",
    "oklch(0.70 0.10 90)",
  ],
  "--sand": [
    "oklch(0.94 0.025 82)",
    "oklch(0.96 0.02 90)",
    "oklch(0.92 0.03 70)",
    "oklch(0.93 0.02 200)",
    "oklch(0.95 0.02 150)",
  ],
  "--ink": [
    "oklch(0.20 0.018 250)",
    "oklch(0.15 0.02 250)",
    "oklch(0.22 0.02 30)",
    "oklch(0.18 0.01 150)",
    "oklch(0.25 0.025 280)",
  ],
};

export const loadTheme = () => {
  try {
    return JSON.parse(localStorage.getItem(THEME_KEY) || "{}");
  } catch {
    return {};
  }
};

export const applyTheme = (tokens) => {
  Object.entries(tokens).forEach(([k, v]) =>
    document.documentElement.style.setProperty(k, v)
  );
};

export const saveTheme = (tokens) => {
  localStorage.setItem(THEME_KEY, JSON.stringify(tokens));
  window.dispatchEvent(new CustomEvent("datanile:theme"));
};

export const resetTheme = () => {
  localStorage.removeItem(THEME_KEY);
  Object.keys(THEME_PALETTE).forEach((k) =>
    document.documentElement.style.removeProperty(k)
  );
  window.dispatchEvent(new CustomEvent("datanile:theme"));
};

export { THEME_KEY };
